  Definition SENV : Prop :=
    umapx MI 32 (nval32 ASEGS) A M obj bl bc ents /\ 0 <= key < 2 ^ 32
    /\ gz M obj 40 /\ (bc <> 0 -> gz M bl (8 * bc)) /\ (forall p k v, In (p, (k, v)) ents -> gz M p 32)
