  Ltac runL R vals sr scr pc :=
    let E := fresh "E" in let HR := fresh "HR" in let HK := fresh "HK" in
    try unfold loop_res;
    pose (E := Eseed R vals);
    assert (HR : regs_ok E sr R) by
      (apply regs_ok_srs; [apply regs_ok_seed|];
       repeat (apply Forall_cons; [cbn [fst snd]; split; [intros X; discriminate X | evs; assumption] |]); apply Forall_nil);
    assert (HK : know_ok ASEGS E M (KNL pc sr scr)) by
      (kn_eval; unfold know_ok; apply Forall_cons; [match goal with W : rw_cells _ M (_ + 976) _ |- _ => kword_cell W 0%nat (C8 (Z_to_bv 64 SHBASE)) end |]; know_tac);
    xrun HR HK 100%nat E_STOPS scr 50%N;
    [ split_scs; try sc_auto1; try sc_shdj;
      try (match goal with Hk : cell4 _ _ _ _ |- _ => unfold cell4 in Hk; sc_rd_sx Hk end);
      try (cbn [sc_denot]; evs; rewrite ?w_remu by lia; rewrite ?br_ne, ?br_eq, ?br_ltu, ?br_geu, ?br_ne_sxw by lia; bool_lia)
    | ].

  Ltac finL_nf :=
    match goal with HR : regs_ok _ _ ?R, HR' : regs_ok ?E' _ ?R', Hms : msteps _ _ (mkst _ _ _ _) |- _ =>
    let AO := fresh "AO" in assert (AO : aonlyN R R') by (aonly_same HR HR');
    exists R'; right; exact (conj Hms AO)
    end.

  Lemma loopM : forall l2 l1 p k v R, SENV ->
    ents = l1 ++ (p, (k, v)) :: l2 -> bc <> 0 ->
    getr R 25%bv = Z_to_bv 64 p -> getr R 11%bv = sxw key -> getr R 2%bv = Z_to_bv 64 S1 -> getr R 9%bv = Z_to_bv 64 S1 ->
    getr R 16%bv = Z_to_bv 64 key -> getr R 23%bv = Z_to_bv 64 bc -> getr R 26%bv = Z_to_bv 64 (hmod key bc) ->
    loop_res R E_LM.
