  Lemma emp_from_bb : forall R (pw : Z), SENV -> bc <> 0 ->
    getr R 2%bv = Z_to_bv 64 S1 -> getr R 9%bv = Z_to_bv 64 S1 -> getr R 16%bv = Z_to_bv 64 key ->
    getr R 15%bv = Z_to_bv 64 (obj / 8) -> getr R 23%bv = Z_to_bv 64 bc -> getr R 26%bv = Z_to_bv 64 (hmod key bc) ->
    getr R 12%bv = Z_to_bv 64 pw -> 0 <= pw < 2 ^ 64 -> (bc <> 2 -> 2 <= pw) -> (bc = 2 -> pw < 2) ->
